// Oblique right-lower-quadrant incision from A to B (patient's right = viewer's left).
const A = [104, 330], B = [262, 420], C = [(A[0] + B[0]) / 2, (A[1] + B[1]) / 2];
const L = Math.hypot(B[0] - A[0], B[1] - A[1]), U = [(B[0] - A[0]) / L, (B[1] - A[1]) / L], N = [-U[1], U[0]];
const lens = w => "M" + A[0] + " " + A[1] + " Q" + (C[0] + N[0] * 2 * w).toFixed(1) + " " + (C[1] + N[1] * 2 * w).toFixed(1) + " " + B[0] + " " + B[1] +
  " Q" + (C[0] - N[0] * 2 * w).toFixed(1) + " " + (C[1] - N[1] * 2 * w).toFixed(1) + " " + A[0] + " " + A[1] + " Z";
const at = f => [A[0] + (B[0] - A[0]) * f, A[1] + (B[1] - A[1]) * f];
let el = {};
function label(api, g, txt, x, y, color, anchor) {
  const t = api.el("text", {x, y, "text-anchor": anchor || "start", "dominant-baseline": "central", "font-size": 18, "font-weight": 800, fill: color, stroke: "#fff", "stroke-width": 5, "paint-order": "stroke", "stroke-linejoin": "round", "font-family": "system-ui,sans-serif"}, g);
  t.textContent = txt; return t;
}
function vis(api, node, o) { api.set(node, {opacity: o.toFixed(3), display: o > 0.001 ? "inline" : "none"}); }
function setup(api) {
  const g = api.$("#woundG");
  el.gap = api.el("path", {d: lens(1.5), fill: "url(#bed)", stroke: "#7a2a2a", "stroke-width": 2, "stroke-linejoin": "round"}, g);
  el.pool = api.el("ellipse", {cx: C[0], cy: C[1], rx: 50, ry: 7, fill: "#e5c13f", transform: "rotate(29.7 " + C[0] + " " + C[1] + ")"}, g);
  el.shine = api.el("g", {fill: "#ffffff"}, g);
  [[0.25, -26], [0.6, -30], [0.45, 30]].forEach(([f, o]) => { const p = at(f);
    api.el("ellipse", {cx: p[0] + N[0] * o, cy: p[1] + N[1] * o, rx: 16, ry: 4, transform: "rotate(29.7 " + (p[0] + N[0] * o) + " " + (p[1] + N[1] * o) + ")", opacity: 0.55}, el.shine); });
  el.beads = [0.18, 0.38, 0.55, 0.72, 0.86].map((f, i) => { const p = at(f);
    return api.el("circle", {cx: p[0] + N[0] * 3, cy: p[1] + N[1] * 3 + 3, r: i % 2 ? 6 : 7.5, fill: "#ecc94b", stroke: "#b8901c", "stroke-width": 1.5}, g); });
  el.stitches = [0.1, 0.26, 0.42, 0.58, 0.74, 0.9].map(f => { const p = at(f), s = api.el("g", {}, g);
    api.el("path", {d: "M" + (p[0] + N[0] * 13).toFixed(1) + " " + (p[1] + N[1] * 13).toFixed(1) + " L" + (p[0] - N[0] * 13).toFixed(1) + " " + (p[1] - N[1] * 13).toFixed(1),
      stroke: "#1f3a6e", "stroke-width": 3.5, "stroke-linecap": "round"}, s);
    api.el("circle", {cx: p[0] + N[0] * 13, cy: p[1] + N[1] * 13, r: 3.5, fill: "#1f3a6e"}, s); return s; });
  // fever chart: swinging spikes after a normal start
  let d = "M452 286", x = 452;
  const pts = [[466, 230], [478, 282], [492, 224], [504, 288], [518, 228], [530, 280], [544, 222], [556, 286], [570, 226], [582, 280]];
  pts.forEach(p => d += " L" + p[0] + " " + p[1]);
  el.swing = api.$("#swing"); api.set(el.swing, {d: d, pathLength: 1});
  el.swTag = label(api, api.$("#ui"), "Swinging", 588, 200, "#c0392b", "end");
  // beat 1 labels
  const ui = api.$("#ui");
  el.lab1 = api.el("g", {}, ui);
  api.el("path", {d: "M150 300 L128 262", stroke: "#c0392b", "stroke-width": 2.5, fill: "none"}, el.lab1);
  label(api, el.lab1, "Red, shiny skin", 70, 250, "#c0392b");
  el.lab2 = api.el("g", {}, ui);
  api.el("path", {d: "M232 408 L262 452", stroke: "#a17a10", "stroke-width": 2.5, fill: "none"}, el.lab2);
  label(api, el.lab2, "Discharge", 220, 466, "#8a6a08");
  // beat 3: pus collected
  el.drops = [0, 1, 2, 3, 4, 5].map(i => api.el("ellipse", {rx: 6, ry: 7.5, fill: "#e5c13f", stroke: "#b8901c", "stroke-width": 1.2}, ui));
  el.track = api.el("path", {d: "M200 392 C 290 300, 440 300, 505 384", fill: "none", stroke: "none"}, ui);
  el.lab3 = api.el("g", {}, ui);
  label(api, el.lab3, "Wound opened", 128, 452, "#16323a");
  el.pot = api.$("#potG"); el.lvl = api.$("#pusLevel"); el.chart = api.$("#chart");
}
function render(t, api) {
  // 1. infection signs
  const inf = api.seg(t, 200, 1400, "ease_out");
  vis(api, api.$("#redness"), inf * (0.9 + 0.1 * Math.sin(t / 300)));
  vis(api, el.shine, api.seg(t, 600, 1300) * (1 - api.seg(t, 4700, 5000)));
  el.beads.forEach((b, i) => { const f = api.seg(t, 900 + i * 160, 1300 + i * 160, "back_out");
    api.set(b, {transform: "translate(0 " + (f * 6).toFixed(1) + ")"}); vis(api, b, Math.min(1, f * 1.5) * (1 - api.seg(t, 4800, 5100))); });
  vis(api, el.lab1, api.seg(t, 700, 1100) * (1 - api.seg(t, 4600, 4800)));
  vis(api, el.lab2, api.seg(t, 1400, 1800) * (1 - api.seg(t, 4600, 4800)));
  // 2. swinging pyrexia draws on
  const sw = api.seg(t, 2400, 4200, "linear");
  api.set(el.swing, {"stroke-dasharray": sw.toFixed(4) + " 1.001", opacity: sw > 0 ? 1 : 0});
  vis(api, el.swTag, api.seg(t, 3900, 4300));
  // 3. sutures out, wound opened, pus to the specimen pot
  el.stitches.forEach((s, i) => { const f = api.seg(t, 4650 + i * 50, 4950 + i * 50);
    vis(api, s, 1 - f); api.set(s, {transform: "translate(0 " + (-f * 14).toFixed(1) + ")"}); });
  const op = api.seg(t, 4800, 5300, "ease_out");
  api.set(el.gap, {d: lens(1.5 + op * 17)});
  vis(api, el.pool, op);
  api.set(el.pool, {rx: (14 + op * 30).toFixed(1), ry: (2 + op * 4).toFixed(1)});
  vis(api, el.pot, api.seg(t, 4650, 5000));
  vis(api, el.lab3, api.seg(t, 5200, 5500));
  el.drops.forEach((d, i) => { const f = api.seg(t, 5000 + i * 110, 5500 + i * 110, "ease_in");
    const p = api.pointAt(el.track, f); api.set(d, {cx: p.x.toFixed(1), cy: p.y.toFixed(1)}); vis(api, d, f > 0 && f < 1 ? 1 : 0); });
  const lv = api.seg(t, 5300, 5900, "ease_out") * 46;
  api.set(el.lvl, {y: (488 - lv).toFixed(1), height: lv.toFixed(1)});
}
